public static class FinalizeReverseMetadata {public static string Main(){EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");var r=UnityEngine.Object.FindAnyObjectByType<Racer.RaceDirector>();r.GetComponent<Racer.BackyardForwardCourse>().anchors[0]=r.gates[0].transform.position-Vector3.up*1.5f;EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());r.road.Initialize();Racer.Editor.BackyardReverseAuthoring.ExportReverse();AssetDatabase.Refresh();return "Finish reference updated to actual street gate; compile final fixture";}}
